create table if not exists public.orders(id bigint generated by default as identity primary key,customer_email text not null,customer_name text not null,address text not null,city text not null,postcode text not null,country text not null default 'Italia',items jsonb not null,total numeric(10,2) not null check(total>=0),status text not null default 'demo_pending',created_at timestamptz not null default now());alter table public.orders enable row level security;create policy "Allow demo order submissions" on public.orders for insert to anon with check(char_length(customer_email)>3 and char_length(customer_name)>0 and jsonb_typeof(items)='array' and total>=0);